draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // seed
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2*Math.PI);
  ctx.stroke();

  // growth
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2, H/2 + 10 + 50*Math.sin(t));
  ctx.stroke();

  // leaves
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10 + 50*Math.sin(t));
  ctx.lineTo(W/2 - 20*Math.cos(2*t), H/2 + 10 + 50*Math.sin(t) - 20*Math.sin(2*t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10 + 50*Math.sin(t));
  ctx.lineTo(W/2 + 20*Math.cos(2*t), H/2 + 10 + 50*Math.sin(t) - 20*Math.sin(2*t));
  ctx.stroke();

  ctx.restore();
}
